-- KDF function
local function kdf(p, s, r)
    s = s or "vm_obf_ultimate_2025"
    r = r or 1000
    local h = 0x5A827999
    for i = 1, #p do
        h = bxor(h, lshift(string.byte(p, i), (i % 24)))
        h = band(h, 0xFFFFFFFF)
    end
    for i = 1, #s do
        local b = string.byte(s, i)
        h = bxor(h, rshift(b, (i % 8)))
        h = bor(h, lshift(b, (24 - i % 24)))
        h = band(h, 0xFFFFFFFF)
    end
    for rd = 1, r do
        h = bxor(h, 0x6ED9EBA1)
        h = band((h * 1103515245 + 12345), 0xFFFFFFFF)
        h = bor(lshift(h, 13), rshift(h, 19))
        h = band(h, 0xFFFFFFFF)
        local b1, b2, b3, b4 = band(rshift(h, 0), 0xFF), band(rshift(h, 8), 0xFF),
            band(rshift(h, 16), 0xFF), band(rshift(h, 24), 0xFF)
        h = bor(lshift(S[b1 + 1], 0), lshift(S[b2 + 1], 8),
            lshift(S[b3 + 1], 16), lshift(S[b4 + 1], 24))
        h = bxor(h, rd * 0x9E3779B9)
        h = band(h, 0xFFFFFFFF)
    end
    return h
end

-- PRNG
local function prng(seed)
    local st = {x = band(seed, 0xFFFFFFFF), y = band(rshift(seed, 16), 0xFFFF) + 0x9E3779B9,
        z = 0x6A09E667, w = 0xBB67AE85, c = 0}
    return function()
        st.c = st.c + 1
        local t = bxor(st.x, lshift(st.x, 11))
        t = band(t, 0xFFFFFFFF)
        st.x, st.y, st.z = st.y, st.z, st.w
        st.w = bxor(bxor(st.w, rshift(st.w, 19)), bxor(t, rshift(t, 8)))
        st.w = band(st.w, 0xFFFFFFFF)
        return band(bxor(st.w, st.c), 0xFF)
    end
end

-- Decryption
local function decrypt(enc, pass, layers)
    layers = layers or 5
    local bytes = {}
    for i = 1, #enc do bytes[i] = enc[i] end
    for layer = layers, 1, -1 do
        if layer < layers then
            local lk = pass .. "_L" .. layer .. "_ULTRA"
            local ps = kdf(lk, "PERM", 50)
            local pp = prng(ps)
            local idx = {}
            for i = #bytes, 2, -1 do
                local j = (pp() % i) + 1
                table.insert(idx, 1, {i, j})
            end
            for _, pr in ipairs(idx) do
                bytes[pr[1]], bytes[pr[2]] = bytes[pr[2]], bytes[pr[1]]
            end
        end
        local lk = pass .. "_L" .. layer .. "_ULTRA"
        local seed = kdf(lk, "LAYER_" .. layer, 100 + layer * 10)
        local pr = prng(seed)
        for i = 1, #bytes do
            local kb = pr()
            bytes[i] = bxor(bytes[i], band(i, 0xFF))
            local rot = band(layer, 0x07)
            bytes[i] = bor(rshift(bytes[i], rot), lshift(bytes[i], 8 - rot))
            bytes[i] = band(bytes[i], 0xFF)
            bytes[i] = IS[bytes[i] + 1]
            bytes[i] = bxor(bytes[i], kb)
            bytes[i] = band(bytes[i], 0xFF)
        end
    end
    local chars = {}
    for i = 1, #bytes do chars[i] = string.char(bytes[i]) end
    return table.concat(chars)
end

